// ===================== DET: ТРЕНАЖЁРЫ =====================
// Каждый тренажёр: (box, {level 1..3, mock}) => Promise<{score,total,skill,notes[]}>
const lvlWords = d => VOCAB.filter(w => !w.word.includes(" ") && w.word.length > 2 && (d === 1 ? ["A1", "A2"] : d === 2 ? ["A2", "B1", "B2"] : ["B2", "C1", "C2"]).includes(w.level));
const DET = {
  "read-select"(box, o) { return new Promise(res => {
    const d = o.level || 2; const real = pick(lvlWords(d), 9).map(w => w.word.toLowerCase()); const fake = pick(DET_PSEUDO, 6); const all = shuffle([...real.map(w => [w, 1]), ...fake.map(w => [w, 0])]);
    box.innerHTML = `<div class="card stack"><div class="row between"><b>Select the real English words in this list.</b><span class="timer" id="dt"></span></div><div class="chips">${all.map(([w], i) => `<button class="chip" data-i="${i}" style="font-size:16px">${esc(w)}</button>`).join("")}</div><button class="btn pri" id="dn">Next</button></div>`;
    const sel = new Set(); $$(".chip", box).forEach(c => c.onclick = () => { const i = +c.dataset.i; sel.has(i) ? sel.delete(i) : sel.add(i); c.classList.toggle("on"); });
    const done = () => { t.stop(); let sc = 0; const notes = []; all.forEach(([w, r], i) => { const s = sel.has(i); if (s === !!r) sc++; else { notes.push(r ? `«${w}» — настоящее слово, а вы его не отметили` : `«${w}» — не существует, но вы его отметили`); logMistake("DET Read and Select", `Это настоящее слово? ${w}`, s ? "да" : "нет", r ? "да" : "нет"); } }); res({ score: sc, total: all.length, skill: "Reading", notes }); };
    const t = countdown($("#dt", box), all.length * 5, done); $("#dn", box).onclick = done; }); },
  "fill-blanks"(box, o) { return new Promise(res => {
    const d = o.level || 2; const n = o.n || 4; const items = pick(lvlWords(d).filter(w => blankWord(w.ex, w.word)), n).map(w => { const m = w.ex.match(new RegExp("\\b" + w.word + "[a-z]*", "i")); const full = m[0]; const k = Math.max(1, Math.floor(full.length / 2)); return { w, full, shown: full.slice(0, k), sent: w.ex.replace(full, "§") }; });
    let i = 0, sc = 0; const notes = [];
    const draw = () => { if (i >= items.length) return res({ score: sc, total: items.length, skill: "Reading", notes }); const it = items[i]; const [a, b] = it.sent.split("§");
      box.innerHTML = `<div class="card stack"><div class="row between"><b>Type the missing letters to complete the text below.</b><span class="timer" id="dt"></span></div><div class="ctest">${esc(a)}<b>${esc(it.shown)}</b><input type="text" id="fi" maxlength="${it.full.length - it.shown.length + 2}" size="${it.full.length - it.shown.length}" autocomplete="off" spellcheck="false">${esc(b)}</div><div class="muted" style="font-size:13px">${i + 1} / ${items.length} · ${esc(it.w.exru)}</div><button class="btn pri" id="dn">Next</button></div>`;
      const inp = $("#fi", box); inp.focus(); const go = () => { t.stop(); const ok = norm(it.shown + inp.value) === norm(it.full); if (ok) sc++; else { notes.push(`${it.full} (вы ввели: ${it.shown + inp.value})`); logMistake("DET Fill in the Blanks", it.w.ex, it.shown + inp.value, it.full); } i++; draw(); };
      const t = countdown($("#dt", box), 20, go); $("#dn", box).onclick = go; inp.onkeydown = e => { if (e.key === "Enter") go(); }; };
    draw(); }); },
  "read-complete"(box, o) { return new Promise(res => {
    const d = o.level || 2; const para = pick(DET_CTEST.filter(p => Math.abs(p[0] - d) <= 1), 1)[0][1]; const sents = para.match(/[^.!?]+[.!?]/g); const first = sents[0]; const rest = para.slice(first.length);
    const gaps = []; let k = 0; const html = rest.replace(/[A-Za-z]+/g, w => { k++; if (k % 2 === 0 && w.length >= 3 && gaps.length < 12) { const s = Math.ceil(w.length / 2) - (w.length > 3 ? 0 : 0); const show = w.slice(0, Math.floor(w.length / 2)); gaps.push({ w, show }); const g = gaps.length - 1; return `${esc(show)}<input type="text" data-g="${g}" maxlength="${w.length - show.length}" size="${w.length - show.length}" autocomplete="off" spellcheck="false">`; } return esc(w); });
    box.innerHTML = `<div class="card stack"><div class="row between"><b>Type the missing letters to complete the text below.</b><span class="timer" id="dt"></span></div><div class="ctest">${esc(first)}${html}</div><button class="btn pri" id="dn">Submit</button></div>`;
    $$("[data-g]", box).forEach((inp, idx, arr) => inp.oninput = () => { if (inp.value.length >= +inp.maxLength && arr[idx + 1]) arr[idx + 1].focus(); });
    const done = () => { t.stop(); let sc = 0; const notes = []; $$("[data-g]", box).forEach(inp => { const g = gaps[+inp.dataset.g]; const ok = norm(g.show + inp.value) === norm(g.w); if (ok) sc++; else notes.push(`${g.w} (вы ввели: ${g.show + inp.value})`); inp.style.borderColor = ok ? "var(--good)" : "var(--bad)"; if (!ok) inp.value = g.w.slice(g.show.length); inp.disabled = true; }); if (notes.length) logMistake("DET Read and Complete", para.slice(0, 80) + "…", notes.join("; "), "см. текст"); setTimeout(() => res({ score: sc, total: gaps.length, skill: "Reading", notes }), o.mock ? 0 : 1); };
    const t = countdown($("#dt", box), 180, done); $("#dn", box).onclick = done; }); },
  "interactive-reading"(box, o) { return new Promise(res => {
    const P = pick(DET_IREAD.filter(p => Math.abs(p.level - (o.level || 2)) <= 1), 1)[0] || DET_IREAD[0]; let sc = 0, tot = 0; const notes = []; let step = 0;
    const T = `<span class="timer" id="dt"></span>`;
    const passageHtml = (mode) => P.text.map((s, i) => { if (mode === "blanks") { const b = P.blanks.find(x => x.i === i); return b ? s.replace(b.w, `<select data-b="${i}" style="width:auto;display:inline-block;padding:2px 6px"><option value="">Select a word</option>${shuffle(b.o).map(x => `<option>${x}</option>`).join("")}</select>`) : esc(s); } if (mode === "missing" && i === P.missingIdx) return `<span class="pill" style="background:var(--gold-soft)">[ ? ]</span>`; return mode === "hl" ? `<span class="tw" data-s="${i}">${esc(s)}</span>` : esc(s); }).join(" ");
    const steps = [
      () => { box.innerHTML = `<div class="card stack"><div class="row between"><b>Complete the Sentences: select the best option for each missing word.</b>${T}</div><div class="reading-text">${passageHtml("blanks")}</div><button class="btn pri" id="dn">Next</button></div>`; $("#dn", box).onclick = () => { P.blanks.forEach(b => { tot++; const v = $(`[data-b="${b.i}"]`, box).value; if (v === b.w) sc++; else notes.push(`Пропуск: ${b.w} (вы: ${v || "—"})`); }); next(); }; },
      () => { const opts = shuffle(P.missingOpts); box.innerHTML = `<div class="card stack"><div class="row between"><b>Complete the Passage: select the best sentence to fill in the blank.</b>${T}</div><div class="reading-text">${passageHtml("missing")}</div>${opts.map((x, k) => `<button class="opt" data-k="${k}">${esc(x)}</button>`).join("")}</div>`; $$(".opt", box).forEach(b => b.onclick = () => { tot++; if (opts[+b.dataset.k] === P.missingOpts[0]) sc++; else notes.push("Пропущенное предложение: " + P.missingOpts[0]); next(); }); },
      () => { box.innerHTML = `<div class="card stack"><div class="row between"><b>Highlight the Answer: click the sentence that answers the question.</b>${T}</div><div class="warn"><b>${esc(P.hq)}</b></div><div class="reading-text">${passageHtml("hl")}</div></div>`; $$("[data-s]", box).forEach(sp => sp.onclick = () => { tot++; if (+sp.dataset.s === P.ha) sc++; else notes.push("Ответ на вопрос: " + P.text[P.ha]); next(); }); },
      () => { box.innerHTML = `<div class="card stack"><div class="row between"><b>Identify the Idea: select the idea that is expressed in the passage.</b>${T}</div><div class="reading-text">${esc(P.text.join(" "))}</div>${P.idea.o.map((x, k) => `<button class="opt" data-k="${k}">${esc(x)}</button>`).join("")}</div>`; $$(".opt", box).forEach(b => b.onclick = () => { tot++; if (+b.dataset.k === P.idea.a) sc++; else notes.push("Главная идея: " + P.idea.o[P.idea.a]); next(); }); },
      () => { box.innerHTML = `<div class="card stack"><div class="row between"><b>Title the Passage: select the best title.</b>${T}</div>${P.titles.o.map((x, k) => `<button class="opt" data-k="${k}">${esc(x)}</button>`).join("")}</div>`; $$(".opt", box).forEach(b => b.onclick = () => { tot++; if (+b.dataset.k === P.titles.a) sc++; else notes.push("Заголовок: " + P.titles.o[P.titles.a]); next(); }); }];
    let left = 420; const tick = setInterval(() => { left--; const el = $("#dt", box); if (el) { el.textContent = `${Math.floor(left / 60)}:${String(left % 60).padStart(2, "0")}`; el.classList.toggle("low", left <= 30); } if (left <= 0) { clearInterval(tick); finish(); } }, 1000); TIMERS.add(tick);
    const finish = () => { clearInterval(tick); TIMERS.delete(tick); const totalQ = 3 + 4; if (tot < totalQ) tot = totalQ; if (notes.length) logMistake("DET Interactive Reading", P.title, notes.join("; "), "см. разбор"); res({ score: sc, total: tot, skill: "Reading", notes }); };
    const next = () => { step++; step < steps.length ? steps[step]() : finish(); }; steps[0](); }); },
  "listen-type"(box, o) { return new Promise(res => {
    const d = o.level || 2; const items = pick(DET_LISTEN.filter(x => x[0] === d), o.n || 3).map(x => x[1]); let i = 0, sc = 0, tot = 0; const notes = [];
    const draw = () => { if (i >= items.length) return res({ score: sc, total: tot, skill: "Listening", notes }); const s = items[i]; let plays = 0;
      box.innerHTML = `<div class="card stack"><div class="row between"><b>Type the statement that you hear.</b><span class="timer" id="dt"></span></div><div class="row"><button class="btn pri" id="pl">🔊 Play (осталось 3)</button><span class="muted">${i + 1} / ${items.length}</span></div><input type="text" id="li" autocomplete="off" spellcheck="false" placeholder="Type here…"><button class="btn" id="dn">Next</button><div id="fb"></div></div>`;
      $("#pl", box).onclick = () => { if (plays >= 3) return; plays++; $("#pl", box).textContent = `🔊 Play (осталось ${3 - plays})`; Audio.speak(s, { rate: 0.95 }); };
      const go = () => { t.stop(); const a = norm(s).split(" "), b = norm($("#li", box).value).split(" "); const ok = a.filter((w, k) => b.includes(w)).length; sc += ok; tot += a.length; if (ok < a.length) { notes.push(`«${s}» — вы: «${$("#li", box).value}»`); logMistake("DET Listen and Type", "Аудио-предложение", $("#li", box).value, s); } i++; draw(); };
      const t = countdown($("#dt", box), 60, go); $("#dn", box).onclick = go; $("#li", box).onkeydown = e => { if (e.key === "Enter") go(); }; };
    draw(); }); },
  "interactive-listening"(box, o) { return new Promise(res => {
    const C = pick(DET_ILISTEN.filter(x => Math.abs(x.level - (o.level || 2)) <= 1), 1)[0] || DET_ILISTEN[0]; let i = 0, sc = 0; const notes = []; const transcript = [];
    const draw = () => { if (i >= C.turns.length) return summary(); const tn = C.turns[i]; const opts = shuffle(tn.o.map((x, k) => [x, k]));
      box.innerHTML = `<div class="card stack"><div class="row between"><b>Listen and Respond</b><span class="pill">${i + 1} / ${C.turns.length}</span></div><div class="muted">${esc(C.context)}</div><div class="row"><button class="btn pri" id="pl">🔊 Прослушать собеседника</button></div><b>Select the best response:</b>${opts.map(([x, k]) => `<button class="opt" data-k="${k}">${esc(x)}</button>`).join("")}</div>`;
      $("#pl", box).onclick = () => Audio.speak(tn.say); setTimeout(() => Audio.speak(tn.say), 300);
      $$(".opt", box).forEach(b => b.onclick = () => { const k = +b.dataset.k; transcript.push("Speaker: " + tn.say, "You: " + tn.o[tn.a]); if (k === tn.a) sc++; else notes.push(`На «${tn.say}» лучше ответить: «${tn.o[tn.a]}»`); i++; draw(); }); };
    const summary = () => { box.innerHTML = `<div class="card stack"><div class="row between"><b>Summarize the Conversation: write a summary of the conversation you just had.</b><span class="timer" id="dt"></span></div><textarea id="sm" placeholder="In the conversation, …"></textarea><button class="btn pri" id="dn">Submit</button></div>`;
      const go = async () => { t.stop(); const text = $("#sm", box).value.trim(); let s2 = 0; const words = (text.match(/[A-Za-z']+/g) || []).length; if (AI.ok && text) { try { const r = await AI.json(`A learner summarised a conversation. Key content (in Russian): ${C.summary}. Transcript: ${transcript.join(" | ")}. Learner summary: """${text}""". Rate 0-10 for content coverage and 0-10 for language accuracy. Return JSON {"content":0,"language":0,"comment_ru":""}`, "quick"); s2 = (r.content + r.language) / 4; notes.push("Резюме: " + r.comment_ru); } catch { s2 = Math.min(5, words / 8); } } else { s2 = Math.min(5, words / 8); notes.push("Резюме оценено по объёму (" + words + " слов). Ключевое содержание: " + C.summary); }
        res({ score: sc + s2, total: C.turns.length + 5, skill: "Listening", notes, text }); };
      const t = countdown($("#dt", box), 75, go); $("#dn", box).onclick = go; };
    draw(); }); },
  "write-photo"(box, o) { const P = pick(PHOTOS, 1)[0]; return openWriting(box, { title: "Write one or more sentences about the image.", photo: P.svg, prompt: "Describe the photo. Context for checker: " + P.desc, shown: "Write one or more sentences about the image.", time: 60, min: 20, level: o.level, mock: o.mock }); },
  "interactive-writing"(box, o) { const pr = pick(DET_PROMPTS.iwrite, 1)[0]; return new Promise(async res => { const a = await openWriting(box, { title: "Interactive Writing — Part 1", prompt: pr[0], shown: pr[0], time: o.short ? 180 : 300, min: 80, level: o.level, noFeedback: true }); const b = await openWriting(box, { title: "Interactive Writing — Part 2 (follow-up)", prompt: pr[1], shown: pr[1], time: o.short ? 120 : 180, min: 50, level: o.level, noFeedback: !!o.mock, combine: a.text }); res(b); }); },
  "writing-sample"(box, o) { const pr = pick(DET_PROMPTS.sample, 1)[0]; return openWriting(box, { title: "Writing Sample", prompt: pr, shown: pr, prep: 30, time: o.short ? 180 : 300, min: 100, level: o.level, mock: o.mock }); },
  "speak-photo"(box, o) { const P = pick(PHOTOS, 1)[0]; return openSpeaking(box, { title: "Speak About the Photo", photo: P.svg, prompt: "Describe the image. Context for checker: " + P.desc, shown: "Speak about the image below for at least 30 seconds.", prep: 20, time: 90, level: o.level, noAudio: true, mock: o.mock }); },
  "read-speak"(box, o) { const pr = pick(DET_PROMPTS.readspeak, 1)[0]; return openSpeaking(box, { title: "Read, Then Speak", prompt: pr[0] + " " + pr.slice(1).join(" "), shown: pr[0], bullets: pr.slice(1), prep: 20, time: 90, level: o.level, noAudio: true, mock: o.mock }); },
  "interactive-speaking"(box, o) { const qs = pick(DET_PROMPTS.ispeak, 1)[0].slice(0, o.short ? 3 : 6); return new Promise(async res => { const ans = []; for (let i = 0; i < qs.length; i++) { const r = await openSpeaking(box, { title: `Interactive Speaking ${i + 1} / ${qs.length}`, prompt: qs[i], shown: "Listen to the question and answer it.", time: 35, level: o.level, hideText: true, noFeedback: true, autoPlay: true }); ans.push(r.text); }
      const all = qs.map((q, i) => `Q: ${q}\nA: ${ans[i] || "(no answer)"}`).join("\n"); if (o.mock) return res({ score: 0, total: 0, skill: "Speaking", text: all, deferred: true, prompt: "Interactive speaking: answer a series of questions" });
      box.innerHTML = `<div id="fbk"></div>`; await speakFeedback($("#fbk", box), { prompt: "Interactive speaking: a series of questions about: " + qs[0], level: LEVELS[Math.min(5, (o.level || 2) + 1)], section: "DET Interactive Speaking" }, all.replace(/Q: .*\nA: /g, ""), 0); res({ score: 1, total: 1, skill: "Speaking", text: all }); }); },
  "speaking-sample"(box, o) { const pr = pick(DET_PROMPTS.sample, 1)[0]; return openSpeaking(box, { title: "Speaking Sample", prompt: pr, shown: pr, prep: 30, time: o.short ? 90 : 180, level: o.level, mock: o.mock }); }
};
function detLevel(o) { return LEVELS[Math.min(5, Math.max(0, (o.level || 2) * 2 - 1))]; }
function openWriting(box, o) { return new Promise(res => {
  box.innerHTML = `<div class="card stack"><div class="row between"><b>${esc(o.title)}</b><span class="timer" id="wt"></span></div>${o.photo ? `<div class="photo" style="max-width:420px">${o.photo}</div>` : ""}<div style="font-size:16px">${esc(o.shown)}</div>${o.combine ? `<div class="muted" style="font-size:13px;border-left:3px solid var(--line);padding-left:10px">${esc(o.combine)}</div>` : ""}<textarea id="wta" ${o.prep ? "disabled" : ""} placeholder="${o.prep ? "Подготовка…" : "Type your response here…"}" spellcheck="false"></textarea><div class="row between"><span class="muted" id="wc">0 words</span><button class="btn pri" id="dn">Submit</button></div></div><div id="wfb" style="margin-top:12px"></div>`;
  const ta = $("#wta", box); ta.oninput = () => $("#wc", box).textContent = (ta.value.match(/[A-Za-z']+/g) || []).length + " words";
  let t; const go = async () => { t?.stop(); $("#dn", box).disabled = true; ta.disabled = true; const text = ta.value.trim(); const full = o.combine ? o.combine + "\n\n" + text : text;
    if (o.noFeedback || o.mock) return res({ text: full, prompt: o.prompt, skill: "Writing", deferred: true, score: 0, total: 0 });
    const r = await showWritingFeedback($("#wfb", box), { prompt: o.prompt, level: detLevel(o), min: o.min, section: "DET " + o.title, skill: "Writing" }, full || "(no answer)"); res({ text: full, score: 1, total: 1, skill: "Writing" }); };
  const start = () => { ta.disabled = false; ta.placeholder = "Type your response here…"; ta.focus(); t = countdown($("#wt", box), o.time, go); };
  if (o.prep) { const p = countdown($("#wt", box), o.prep, start); $("#dn", box).onclick = () => { if (ta.disabled && !$("#dn", box).disabled) { p.stop(); start(); } else go(); }; } else { start(); $("#dn", box).onclick = go; }
}); }
function openSpeaking(box, o) { return new Promise(res => {
  box.innerHTML = `<div class="card stack"><div class="row between"><b>${esc(o.title)}</b><span class="timer" id="st"></span></div>${o.photo ? `<div class="photo" style="max-width:420px">${o.photo}</div>` : ""}<div style="font-size:16px">${o.hideText ? "" : esc(o.shown)}</div>${o.hideText ? `<div class="row">${spk(o.prompt)}<span class="muted">Нажмите, чтобы прослушать вопрос ещё раз</span></div>` : ""}${o.bullets ? `<ul>${o.bullets.map(b => `<li>${esc(b)}</li>`).join("")}</ul>` : ""}
  <div class="row">${Mic.available() ? `<button class="btn acc mic" id="smic">🎙 Говорить</button>` : ""}<span class="muted" id="sst">${o.prep ? "Подготовка…" : "Отвечайте"}</span></div><textarea id="sta" style="min-height:90px" placeholder="${Mic.available() ? "Транскрипт появится здесь (можно поправить)" : "Микрофон недоступен — введите ответ текстом"}"></textarea><button class="btn pri" id="dn">Submit</button></div><div id="sfb" style="margin-top:12px"></div>`;
  const ta = $("#sta", box); let t, t0 = 0;
  if (o.autoPlay) setTimeout(() => Audio.speak(o.prompt), 300);
  const mb = $("#smic", box); if (mb) mb.onclick = async () => { if (Mic.active) ta.value = await Mic.stop() || ta.value; else { t0 = Date.now(); Mic.start(x => ta.value = x); } };
  const go = async () => { t?.stop(); if (Mic.active) ta.value = await Mic.stop() || ta.value; $("#dn", box).disabled = true; const text = ta.value.trim(); const dur = t0 ? (Date.now() - t0) / 1000 : 0;
    if (o.noFeedback || o.mock) return res({ text, prompt: o.prompt, skill: "Speaking", deferred: true, score: 0, total: 0 });
    await speakFeedback($("#sfb", box), { prompt: o.prompt, level: detLevel(o), section: "DET " + o.title }, text || "(no answer)", dur); markDaily("out"); res({ text, score: 1, total: 1, skill: "Speaking" }); };
  const start = () => { $("#sst", box).textContent = "Отвечайте!"; t = countdown($("#st", box), o.time, go); };
  if (o.prep) { countdown($("#st", box), o.prep, start); } else start(); $("#dn", box).onclick = go;
}); }

VIEWS.det = (v, id) => {
  const s = S();
  if (!id) { v.innerHTML = `<h1>Duolingo English Test Preparation</h1><p class="sub">Тренажёры всех 13 типов заданий DET. Время и формат соответствуют официальному гайду DET Question Guide 2026 (проверено 16.11.2026). Перед экзаменом сверяйтесь с <a href="https://englishtest.duolingo.com" target="_blank" rel="noopener">официальным сайтом</a>: формат может меняться.</p>
    <div class="warn" style="margin-bottom:14px;font-size:14px">Все задания — собственные тренировочные материалы аналогичного формата. Это не реальные вопросы экзамена и не материалы Duolingo. Платформа не связана с Duolingo.</div>
    <div class="card row between" style="margin-bottom:14px"><div><b>⏱ Mock Test</b><div class="muted">Полная имитация экзамена с адаптивной сложностью и итоговым отчётом.</div></div><a class="btn acc" href="#mock">Начать пробный экзамен</a></div>
    <div class="card" style="margin-bottom:14px"><h3>Шкала DET</h3><p style="margin:0">Общий балл и 4 субсчёта (Reading, Listening, Writing, Speaking) — от 10 до 160 с шагом 5; общий балл — среднее четырёх субсчетов. Тест адаптивный: балл не равен простому числу верных ответов.</p></div>
    ${["Reading", "Listening", "Writing", "Speaking"].map(sk => `<h2 style="margin-top:18px">${sk}</h2><div class="grid g3">${DET_TASKS.filter(t => t.skill === sk).map(t => { const st = s.det[t.id]; return `<a class="card link stack" href="#det-${t.id}" style="text-decoration:none;color:inherit"><b>${esc(t.name)}</b><div class="muted" style="font-size:13px">${esc(t.ru)}</div><div class="row between"><span class="pill">⏱ ${esc(t.time)}</span>${st ? `<span class="pill">${st.runs}× · ${st.avg}%</span>` : ""}</div></a>`; }).join("")}</div>`).join("")}`; return; }
  const T = DET_TASKS.find(t => t.id === id); if (!T) return (location.hash = "det");
  const st = s.det[id];
  v.innerHTML = `<a href="#det">← DET Preparation</a><div class="row" style="margin:10px 0"><span class="pill">${T.skill}</span><h1 style="margin:0">${esc(T.name)}</h1></div><p class="sub">${esc(T.ru)}</p>
  <div class="grid g2" id="dinfo"><div class="card stack"><h3>Суть задания</h3><p>${esc(T.desc)}</p><div><b>Время:</b> ${esc(T.time)}</div></div><div class="card stack"><h3>Советы</h3><ul>${T.tips.map(x => `<li>${esc(x)}</li>`).join("")}</ul></div></div>
  <div class="card row between" style="margin-top:14px"><div><b>Статистика:</b> ${st ? `${st.runs} попыток · средний результат ${st.avg}% · лучший ${st.best}%` : "ещё нет попыток"}</div><div class="row"><select id="dlev" style="width:auto"><option value="1">Лёгкий</option><option value="2" selected>Средний</option><option value="3">Сложный</option></select><button class="btn pri" id="dstart">▶ Начать тренировку</button></div></div>
  <div id="dbox" style="margin-top:14px"></div>`;
  $("#dstart").onclick = async () => { $("#dinfo").classList.add("hide"); const box = $("#dbox"); const r = await DET[id](box, { level: +$("#dlev").value }); const p = r.total ? Math.round(100 * r.score / r.total) : null;
    if (p !== null && r.total > 1) { record("DET " + T.name, r.skill, r.score, r.total, { route: "det-" + id }); const d = s.det[id] || { runs: 0, best: 0, sum: 0 }; d.runs++; d.sum = (d.sum || 0) + p; d.avg = Math.round(d.sum / d.runs); d.best = Math.max(d.best, p); s.det[id] = d; Store.save();
      box.insertAdjacentHTML("beforeend", `<div class="card stack" style="margin-top:12px"><h2>Результат: ${Math.round(r.score * 10) / 10} / ${r.total} (${p}%)</h2><div class="bar"><i style="width:${p}%"></i></div>${r.notes?.length ? `<h3>Анализ ошибок</h3>${r.notes.map(n => `<div class="err" style="font-size:14px">${esc(n)}</div>`).join("")}` : '<div class="note">Без ошибок!</div>'}<div class="row"><button class="btn pri" data-act="go" data-to="det-${id}" id="again">Ещё раз</button><a class="btn" href="#det">Все задания</a></div></div>`); $("#again").onclick = () => route(); }
    else { const d = s.det[id] || { runs: 0, best: 0, sum: 0, avg: 0 }; d.runs++; s.det[id] = d; Store.save(); box.insertAdjacentHTML("beforeend", `<div class="row" style="margin-top:12px"><button class="btn pri" id="again">Ещё раз</button><a class="btn" href="#det">Все задания</a></div>`); $("#again").onclick = () => route(); } };
};

