VIEWS.mock = v => {
  const hist = S().mocks;
  v.innerHTML = `<h1>Mock Test</h1><p class="sub">Пробный экзамен в формате, приближённом к DET: последовательность разных заданий, таймеры, случайные вопросы и адаптивная сложность.</p>
  <div class="warn" style="margin-bottom:14px;font-size:14px">Это неофициальная имитация. Она не воспроизводит алгоритм оценки Duolingo, и прогноз балла — лишь ориентир, а не гарантия результата на реальном экзамене.</div>
  <div class="grid g2"><div class="card stack"><h3>Полный режим (~45–55 минут)</h3><p class="muted">Read and Select, Fill in the Blanks, Read and Complete, Listen and Type, Interactive Reading, Interactive Listening, Write About the Photo, Speak About the Photo, Read Then Speak, Interactive Writing, Interactive Speaking, Writing Sample, Speaking Sample.</p><button class="btn acc" id="mFull">▶ Начать полный тест</button></div>
  <div class="card stack"><h3>Короткий режим (~20 минут)</h3><p class="muted">По одному заданию каждого основного типа с сокращённым временем на письмо и речь.</p><button class="btn pri" id="mShort">▶ Начать короткий тест</button></div></div>
  ${hist.length ? `<h2 style="margin-top:20px">История пробных экзаменов</h2><div class="card"><table class="t"><tr><th>Дата</th><th>Режим</th><th>Reading</th><th>Listening</th><th>Writing</th><th>Speaking</th><th>Прогноз*</th></tr>${hist.slice().reverse().map(h => `<tr><td>${new Date(h.d).toLocaleString("ru-RU")}</td><td>${h.mode}</td><td>${h.sk.Reading}%</td><td>${h.sk.Listening}%</td><td>${h.sk.Writing ?? "—"}%</td><td>${h.sk.Speaking ?? "—"}%</td><td><b>${h.est}</b></td></tr>`).join("")}</table><p class="muted" style="font-size:12px">* неофициальная оценка</p></div>` : ""}`;
  $("#mFull").onclick = () => runMock(v, false); $("#mShort").onclick = () => runMock(v, true);
};
async function runMock(v, short) {
  const seq = short ? ["read-select", "fill-blanks", "read-complete", "listen-type", "interactive-reading", "write-photo", "speak-photo", "writing-sample"] : ["read-select", "fill-blanks", "read-select", "read-complete", "listen-type", "fill-blanks", "interactive-reading", "listen-type", "interactive-listening", "write-photo", "speak-photo", "read-speak", "interactive-writing", "interactive-speaking", "writing-sample", "speaking-sample"];
  let level = 2; const res = []; const t0 = Date.now(); const route0 = CUR;
  for (let i = 0; i < seq.length; i++) {
    if (CUR !== route0) return;
    const T = DET_TASKS.find(t => t.id === seq[i]);
    v.innerHTML = `<div class="row between"><h2 style="margin:0">Mock Test · ${esc(T.name)}</h2><span class="pill">Задание ${i + 1} / ${seq.length} · сложность ${["", "лёгкая", "средняя", "высокая"][level]}</span></div><div class="bar" style="margin:10px 0 14px"><i style="width:${100 * i / seq.length}%"></i></div><div id="mbox"></div>`;
    const r = await DET[seq[i]]($("#mbox"), { level, mock: true, short, n: short ? 3 : 4 }); r.task = T.name; res.push(r);
    if (r.total && !r.deferred) { const p = r.score / r.total; level = p >= 0.8 ? Math.min(3, level + 1) : p < 0.5 ? Math.max(1, level - 1) : level; }
  }
  v.innerHTML = `<div class="card"><h2>⏳ Анализируем письменные и устные ответы…</h2><p class="muted">Это может занять до минуты.</p></div>`;
  for (const r of res.filter(r => r.deferred)) {
    const text = r.text || ""; const wc = (text.match(/[A-Za-z']+/g) || []).length;
    if (AI.ok && wc) { try { const a = r.skill === "Writing" ? await AI.checkWriting(r.prompt, text, "B2") : await AI.checkSpeaking(r.prompt, text, "B2"); const sc = Object.values(a.scores || {}).filter(x => typeof x === "number"); r.score = sc.reduce((x, y) => x + y, 0); r.total = sc.length * 10; r.notes = (a.tips_ru || []).slice(0, 2); r.cefr = a.estimated_cefr; (a.errors || []).slice(0, 5).forEach(e => logMistake("Mock " + r.task, `«${e.original}»`, e.original, e.fix, e.explanation_ru)); continue; } catch {} }
    const b = basicCheck(text || " "); r.score = Math.min(10, wc / (r.skill === "Writing" ? 10 : 8)) + Math.max(0, 10 - b.errors.length); r.total = 20; r.notes = [AI.ok ? "Оценено базовой проверкой." : "AI недоступен — оценка по объёму и базовой проверке ошибок."];
  }
  const sk = {}; ["Reading", "Listening", "Writing", "Speaking"].forEach(k => { const rs = res.filter(r => r.skill === k && r.total); sk[k] = rs.length ? Math.round(100 * rs.reduce((a, r) => a + r.score, 0) / rs.reduce((a, r) => a + r.total, 0)) : null; });
  const totS = res.reduce((a, r) => a + (r.total ? r.score : 0), 0), totT = res.reduce((a, r) => a + (r.total || 0), 0);
  const toDet = p => p === null ? null : Math.round((10 + p / 100 * (70 + level * 26)) / 5) * 5; // грубая эвристика: % и достигнутая сложность → 10..160
  const subs = Object.fromEntries(Object.entries(sk).map(([k, p]) => [k, Math.min(160, toDet(p))])); const vals = Object.values(subs).filter(x => x !== null); const est = vals.length ? Math.min(160, Math.ceil(vals.reduce((a, b) => a + b, 0) / vals.length / 5) * 5) : "—";
  const estRange = typeof est === "number" ? `${Math.max(10, est - 15)}–${Math.min(160, est + 15)}` : "—";
  S().mocks.push({ d: Date.now(), mode: short ? "короткий" : "полный", sk, est: estRange }); Object.entries(sk).forEach(([k, p]) => p !== null && S().skill[k].push(p)); markActive(); Store.save();
  const weak = Object.entries(sk).filter(([, p]) => p !== null).sort((a, b) => a[1] - b[1]); const RU = { Reading: "Reading", Listening: "Listening", Writing: "Writing", Speaking: "Speaking" };
  const recs = { Reading: "Тренируйте Read and Complete и Fill in the Blanks, учите слова уровня B1–B2, обращайте внимание на словообразование.", Listening: "Ежедневно делайте Listen and Type, слушайте подкасты на скорости 0.9×, а затем 1×.", Writing: "Пишите по одному тексту в день, используйте связующие слова и проверяйте артикли и времена.", Speaking: "Отвечайте вслух на вопросы каждый день, записывайте себя, учите фразы для начала и завершения ответа." };
  const correct = res.filter(r => !r.deferred).reduce((a, r) => a + r.score, 0), objTot = res.filter(r => !r.deferred).reduce((a, r) => a + r.total, 0);
  v.innerHTML = `<h1>Итоговый отчёт Mock Test</h1><p class="sub">Время: ${Math.round((Date.now() - t0) / 60000)} мин · достигнутая сложность: ${["", "лёгкая", "средняя", "высокая"][level]}</p>
  <div class="grid g4"><div class="card"><div class="stat-l">Правильных (закрытые задания)</div><div class="stat">${Math.round(correct * 10) / 10}</div></div><div class="card"><div class="stat-l">Ошибок</div><div class="stat">${Math.round((objTot - correct) * 10) / 10}</div></div><div class="card"><div class="stat-l">Процент выполнения</div><div class="stat">${Math.round(100 * totS / Math.max(1, totT))}%</div></div><div class="card"><div class="stat-l">Прогноз DET*</div><div class="stat">${estRange}</div></div></div>
  <div class="card" style="margin-top:14px"><h3>Результаты по навыкам</h3>${Object.entries(sk).map(([k, p]) => `<div class="row between" style="margin:8px 0"><b style="width:100px">${k}</b><div class="bar" style="flex:1"><i style="width:${p ?? 0}%"></i></div><span style="width:120px;text-align:right">${p ?? "—"}% ${subs[k] ? `<span class="muted">≈ ${subs[k]}</span>` : ""}</span></div>`).join("")}<p class="muted" style="font-size:12.5px">* Неофициальная оценка по собственной эвристике (доля верных ответов с учётом достигнутой сложности). Не является результатом Duolingo English Test и не гарантирует балл на реальном экзамене.</p></div>
  <div class="grid g2" style="margin-top:14px"><div class="card stack"><h3>Слабые места</h3>${weak.slice(0, 2).map(([k, p]) => `<div class="warn"><b>${RU[k]} — ${p}%.</b> ${recs[k]}</div>`).join("")}</div><div class="card stack"><h3>По заданиям</h3>${res.map(r => `<div class="row between" style="font-size:14px;border-bottom:1px solid var(--line);padding:4px 0"><span>${esc(r.task)}</span><b>${r.total ? Math.round(100 * r.score / r.total) + "%" : "—"}</b></div>`).join("")}</div></div>
  <div class="card stack" style="margin-top:14px"><h3>Комментарии и ошибки</h3>${res.filter(r => r.notes?.length).map(r => `<div><b>${esc(r.task)}:</b><ul style="margin:4px 0">${r.notes.slice(0, 4).map(n => `<li style="font-size:14px">${esc(n)}</li>`).join("")}</ul></div>`).join("") || "Нет замечаний."}</div>
  <div class="row" style="margin-top:14px"><a class="btn pri" href="#mistakes">Журнал ошибок</a><a class="btn" href="#det">Тренажёры DET</a><button class="btn" id="mAgain">Пройти ещё раз</button></div>`;
  $("#mAgain").onclick = () => route();
}

