function barChart(data, max = 100, h = 140) { const w = 100 / data.length; return `<svg viewBox="0 0 ${data.length * 40} ${h + 24}" style="width:100%;height:${h + 24}px">${data.map(([l, val], i) => { const bh = val === null ? 0 : (val / max) * h; return `<rect x="${i * 40 + 8}" y="${h - bh}" width="24" height="${bh}" rx="5" fill="var(--teal)"/><text x="${i * 40 + 20}" y="${h + 16}" text-anchor="middle" font-size="10" fill="var(--muted)">${esc(l)}</text>${val !== null ? `<text x="${i * 40 + 20}" y="${h - bh - 4}" text-anchor="middle" font-size="10" fill="var(--ink2)">${Math.round(val)}</text>` : ""}`; }).join("")}</svg>`; }
VIEWS.progress = v => {
  const s = S(); const learned = SRS.learned(); const due = SRS.due().length; const L = s.profile.level;
  const allG = Object.values(GRAMMAR_TOPICS).flat().length; const gDone = Object.keys(s.grammar).length;
  const totalPct = Math.round(100 * (learned / VOCAB.length * 0.5 + gDone / allG * 0.5));
  const days = Array.from({ length: 30 }, (_, i) => new Date(Date.now() - (29 - i) * 864e5).toISOString().slice(0, 10));
  const totalMin = Object.values(s.activity).reduce((a, b) => a + b, 0);
  const week = days.slice(-14).map(d => [d.slice(8), s.activity[d] || 0]); const wmax = Math.max(10, ...week.map(x => x[1]));
  const skills = ["Reading", "Listening", "Writing", "Speaking", "Vocabulary", "Grammar"].map(k => [k.slice(0, 5), skillAvg(k)]);
  const lvl = LEVELS.map(l => { const ws = VOCAB.filter(w => w.level === l); return [l, 100 * ws.filter(w => SRS.status(w.id) !== "new").length / Math.max(1, ws.length)]; });
  const tests = s.history.filter(h => /Экзамен|Grammar|Reading|Listening|DET|Диагност/.test(h.section)).slice(-12).reverse();
  const st = { new: 0, learning: 0, review: 0, known: 0 }; VOCAB.forEach(w => st[SRS.status(w.id)]++);
  v.innerHTML = `<h1>Мой прогресс</h1><p class="sub">Уровень: ${lv(L)} ${LEVEL_INFO[L].ru}</p>
  <div class="grid g4"><div class="card"><div class="stat-l">Прохождение курса</div><div class="stat">${totalPct}%</div><div class="bar"><i style="width:${totalPct}%"></i></div></div><div class="card"><div class="stat-l">Изучено слов</div><div class="stat">${learned}</div><div class="muted" style="font-size:12px">из ${VOCAB.length}</div></div><div class="card"><div class="stat-l">Нужно повторить</div><div class="stat">${due}</div></div><div class="card"><div class="stat-l">Тем грамматики</div><div class="stat">${gDone}</div><div class="muted" style="font-size:12px">из ${allG}</div></div>
  <div class="card"><div class="stat-l">Упражнений выполнено</div><div class="stat">${s.history.length}</div></div><div class="card"><div class="stat-l">Время обучения</div><div class="stat">${totalMin >= 60 ? Math.floor(totalMin / 60) + " ч " + (totalMin % 60) + " м" : totalMin + " мин"}</div></div><div class="card"><div class="stat-l">Серия дней</div><div class="stat">🔥 ${s.streak.count}</div></div><div class="card"><div class="stat-l">Пробных экзаменов</div><div class="stat">${s.mocks.length}</div></div></div>
  <div class="grid g2" style="margin-top:14px"><div class="card"><h3>Навыки (средний % за последние попытки)</h3>${barChart(skills)}</div><div class="card"><h3>Время обучения, мин (14 дней)</h3>${barChart(week, wmax)}</div>
  <div class="card"><h3>Ежедневная активность (30 дней)</h3><div class="heat">${days.map(d => { const m = s.activity[d] || 0; return `<i title="${d}: ${m} мин" style="background:${m ? `color-mix(in srgb,var(--teal) ${Math.min(100, 25 + m * 3)}%,var(--surface2))` : "var(--surface2)"}"></i>`; }).join("")}</div></div>
  <div class="card"><h3>Слова по статусу</h3>${Object.entries(st).map(([k, n]) => `<div class="row between"><span>${STATUS_RU[k]}</span><b>${n}</b></div><div class="bar" style="margin-bottom:6px"><i style="width:${100 * n / VOCAB.length}%"></i></div>`).join("")}</div>
  <div class="card"><h3>Освоение словаря по уровням, %</h3>${barChart(lvl)}</div>
  <div class="card stack"><h3>Слабые стороны и рекомендации</h3>${recommendations().map(r => `<div class="note" style="font-size:14px">${esc(r[0])} <a href="#${r[1]}">Перейти →</a></div>`).join("")}${(() => { const bad = Object.entries(s.grammar).filter(([, p]) => p < 70).map(([id]) => topicMeta(id)).filter(Boolean); return bad.length ? `<div class="warn" style="font-size:14px">Повторите темы грамматики: ${bad.map(b => esc(b.title)).join(", ")}</div>` : ""; })()}</div></div>
  <h2 style="margin-top:18px">Результаты тестов</h2><div class="card" style="overflow-x:auto"><table class="t"><tr><th>Дата</th><th>Раздел</th><th>Результат</th></tr>${tests.map(h => `<tr><td>${new Date(h.d).toLocaleString("ru-RU")}</td><td>${esc(h.section)}</td><td>${Math.round(100 * h.score / h.total)}%</td></tr>`).join("") || '<tr><td colspan="3" class="muted">Пока нет результатов.</td></tr>'}</table></div>
  <h2 style="margin-top:18px">Пройденные темы грамматики</h2><div class="chips">${Object.entries(s.grammar).map(([id, p]) => `<a class="chip" href="#lesson-${id}" style="text-decoration:none;color:inherit">${esc(topicMeta(id)?.title || id)} · ${p}%</a>`).join("") || '<span class="muted">Пока нет.</span>'}</div>`;
};

// ===================== ЖУРНАЛ ОШИБОК =====================
VIEWS.mistakes = v => {
  const s = S(); let filter = "open";
  const draw = () => {
    const list = s.mistakes.filter(m => filter === "all" || (filter === "open" ? !m.fixed : m.fixed)); const secs = [...new Set(s.mistakes.map(m => m.section.split(":")[0]))];
    v.innerHTML = `<h1>Журнал ошибок</h1><p class="sub">Все неправильно выполненные задания сохраняются автоматически. Повторяйте их, пока ошибка не исчезнет.</p>
    <div class="row" style="margin-bottom:12px"><div class="tabs" style="margin:0">${[["open", "Не исправлены"], ["fixed", "Исправлены"], ["all", "Все"]].map(([k, n]) => `<button class="tab ${filter === k ? "on" : ""}" data-f="${k}">${n} (${s.mistakes.filter(m => k === "all" || (k === "open" ? !m.fixed : m.fixed)).length})</button>`).join("")}</div><button class="btn pri" id="mRev" ${s.mistakes.some(m => !m.fixed) ? "" : "disabled"}>🔁 Повторить ошибки</button></div>
    ${secs.length ? `<div class="muted" style="font-size:13px;margin-bottom:8px">Разделы: ${secs.map(x => `${esc(x)} (${s.mistakes.filter(m => m.section.startsWith(x)).length})`).join(" · ")}</div>` : ""}
    ${list.length ? `<div class="card" style="overflow-x:auto"><table class="t"><tr><th>Вопрос</th><th>Ваш ответ</th><th>Правильно</th><th>Объяснение</th><th>Дата</th><th>Раз</th><th></th></tr>${list.slice(0, 150).map(m => `<tr><td><span class="pill">${esc(m.section)}</span><br>${esc(m.q)}</td><td style="color:var(--bad)">${esc(m.user)}</td><td style="color:var(--good)"><b>${esc(m.correct)}</b></td><td style="font-size:13px">${esc(m.expl)}</td><td style="font-size:12px">${new Date(m.date).toLocaleDateString("ru-RU")}</td><td>${m.count}</td><td><button class="btn sm ghost" data-fix="${esc(m.key)}">${m.fixed ? "↩" : "✓"}</button></td></tr>`).join("")}</table></div>` : `<div class="card">Здесь пока пусто. ${filter === "open" ? "Отлично — нет неисправленных ошибок!" : ""}</div>`}`;
    $$("[data-f]", v).forEach(b => b.onclick = () => { filter = b.dataset.f; draw(); });
    $$("[data-fix]", v).forEach(b => b.onclick = () => { const m = s.mistakes.find(x => x.key === b.dataset.fix); m.fixed = !m.fixed; Store.save(); draw(); });
    $("#mRev").onclick = () => mistakeReview(v);
  };
  draw();
};
function mistakeReview(v) {
  const s = S(); const open = s.mistakes.filter(m => !m.fixed && m.correct && m.correct !== "см. текст" && m.correct !== "см. разбор").slice(0, 10);
  v.innerHTML = `<a href="#mistakes">← Журнал ошибок</a><h1 style="margin-top:10px">Повторение ошибок</h1><p class="sub">Вспомните правильный ответ. Верно — ошибка отмечается как исправленная.</p><div id="mq"></div>`;
  const items = open.map(m => { const others = pick(s.mistakes.filter(x => x !== m && x.correct && x.correct.length < 60).map(x => x.correct), 2); const o = shuffle([...new Set([m.correct, m.user, ...others])].filter(x => x && x !== "(пусто)" && x !== "не вспомнил").slice(0, 4)); return { m, q: m.q, o: o.includes(m.correct) ? o : [m.correct, ...o], e: m.expl }; }).map(it => ({ ...it, a: it.o.indexOf(it.m.correct) }));
  if (!items.length) { $("#mq").innerHTML = `<div class="card">Нечего повторять.</div>`; return; }
  runQuiz($("#mq"), items, { section: "Повторение ошибок", onDone: (sc, t, res) => { res.forEach((r, i) => { if (r.ok) items[i].m.fixed = true; }); Store.save(); $("#mq").innerHTML = resultCard(sc, t) + `<div class="note" style="margin-top:10px">Исправлено ошибок: ${res.filter(r => r.ok).length}</div>`; } });
}

// ===================== НАСТРОЙКИ =====================
VIEWS.settings = v => {
  const s = S(), st = s.settings;
  v.innerHTML = `<h1>Настройки</h1><div class="grid g2"><div class="card stack"><h3>Профиль</h3><div><label class="f">Имя</label><input type="text" id="sName" value="${esc(s.profile.name)}"></div><div><label class="f">Текущий уровень</label><select id="sLv">${LEVELS.map(l => `<option ${l === s.profile.level ? "selected" : ""}>${l}</option>`).join("")}</select></div><div class="muted" style="font-size:13px">Хранилище: ${Store.mode === "cloud" ? "☁️ аккаунт Claude (синхронизация между устройствами)" : "💾 этот браузер (локальный профиль)"} · <span id="cloudStatus"></span></div><div class="row"><button class="btn" id="sOut">Выйти из профиля</button></div></div>
  <div class="card stack"><h3>Оформление</h3><div class="chips">${[["light", "☀️ Светлая"], ["dark", "🌙 Тёмная"], ["auto", "🖥 Как в системе"]].map(([k, n]) => `<button class="chip ${st.theme === k ? "on" : ""}" data-th="${k}">${n}</button>`).join("")}</div></div>
  <div class="card stack"><h3>Произношение</h3><div><label class="f">Акцент по умолчанию</label><select id="sAcc"><option value="en-GB" ${st.accent === "en-GB" ? "selected" : ""}>🇬🇧 Британский</option><option value="en-US" ${st.accent === "en-US" ? "selected" : ""}>🇺🇸 Американский</option></select></div><div><label class="f">Скорость речи: <span id="rv">${st.rate}</span>×</label><input type="range" id="sRate" min="0.6" max="1.3" step="0.05" value="${st.rate}" style="width:100%"></div><div><label class="f">Движок озвучки</label><select id="sEng"><option value="auto" ${st.engine === "auto" ? "selected" : ""}>Автоматически</option><option value="claude" ${st.engine === "claude" ? "selected" : ""}>Голос Claude ${Audio.tts ? "" : "(недоступен)"}</option><option value="browser" ${st.engine === "browser" ? "selected" : ""}>Голоса браузера (${Audio.voices.length})</option></select></div><label class="row"><input type="checkbox" id="sAuto" ${st.autoplay !== false ? "checked" : ""}> Автоматически озвучивать слова в карточках</label><button class="btn" data-act="say" data-t="The quick brown fox jumps over the lazy dog.">🔊 Проверить звук</button></div>
  <div class="card stack"><h3>Ежедневный план</h3><div><label class="f">Новых слов в день</label><input type="number" id="sNew" min="3" max="50" value="${st.dailyNew}"></div><div><label class="f">Слов на повторение за сессию</label><input type="number" id="sRev" min="5" max="100" value="${st.dailyReview}"></div></div>
  <div class="card stack"><h3>Данные</h3><p class="muted" style="font-size:13px">Сохраните резервную копию прогресса (JSON) или перенесите его на другое устройство.</p><div class="row"><button class="btn" id="sExp">📋 Копировать резервную копию</button><button class="btn" id="sImp">📥 Восстановить из копии</button><button class="btn" id="sReset" style="color:var(--bad)">Сбросить прогресс</button></div></div></div>`;
  const sv = () => { Store.save(); };
  $("#sName").onchange = e => { s.profile.name = e.target.value; sv(); }; $("#sLv").onchange = e => { s.profile.level = e.target.value; sv(); toast("Уровень: " + e.target.value); };
  $$("[data-th]", v).forEach(b => b.onclick = () => { st.theme = b.dataset.th; sv(); applyTheme(); $$("[data-th]", v).forEach(x => x.classList.toggle("on", x === b)); });
  $("#sAcc").onchange = e => { st.accent = e.target.value; sv(); }; $("#sRate").oninput = e => { st.rate = +e.target.value; $("#rv").textContent = st.rate; sv(); }; $("#sEng").onchange = e => { st.engine = e.target.value; sv(); }; $("#sAuto").onchange = e => { st.autoplay = e.target.checked; sv(); };
  $("#sNew").onchange = e => { st.dailyNew = Math.max(3, Math.min(50, +e.target.value || 10)); sv(); }; $("#sRev").onchange = e => { st.dailyReview = Math.max(5, Math.min(100, +e.target.value || 20)); sv(); };
  $("#sOut").onclick = () => { Store.logout(); location.hash = "login"; route(); };
  $("#sExp").onclick = async () => { try { await navigator.clipboard.writeText(JSON.stringify(s)); toast("Копия скопирована в буфер обмена"); } catch { modal(`<h2>Резервная копия</h2><p class="muted">Скопируйте текст вручную:</p><textarea style="min-height:240px">${esc(JSON.stringify(s))}</textarea>`); } };
  $("#sImp").onclick = () => { modal(`<h2>Восстановить прогресс</h2><textarea id="impT" placeholder="Вставьте JSON резервной копии"></textarea><button class="btn pri" id="impB" style="margin-top:10px">Восстановить</button>`); $("#impB").onclick = () => { try { const d = JSON.parse($("#impT").value); if (!d.profile || !d.words) throw 0; Store.state = Object.assign(DEFAULT_STATE(), d); Store.save(true); closeModal(); toast("Прогресс восстановлен"); route(); } catch { toast("Неверный формат копии"); } }; };
  $("#sReset").onclick = () => { modal(`<h2>Сбросить весь прогресс?</h2><p>Это действие нельзя отменить. Будут удалены изученные слова, результаты, журнал ошибок и история.</p><div class="row"><button class="btn" data-act="closeModal">Отмена</button><button class="btn acc" id="rsY">Да, сбросить</button></div>`); $("#rsY").onclick = () => { const name = s.profile.name; Store.state = DEFAULT_STATE(); Store.state.profile.name = name; Store.save(true); closeModal(); route(); }; };
};

// ===================== АДМИН-ПАНЕЛЬ =====================
function contentIssues() {
  const iss = []; const seen = {};
  VOCAB.forEach(w => { const k = w.word.toLowerCase() + "|" + w.pos; if (seen[k] && seen[k] !== w.level) iss.push(["warn", `Повтор слова «${w.word}» на уровнях ${seen[k]} и ${w.level}`, w.id]); seen[k] = seen[k] || w.level;
    if (!w.ru) iss.push(["err", `Нет перевода: ${w.word}`, w.id]); if (!w.ipa) iss.push(["err", `Нет IPA: ${w.word}`, w.id]); if (!w.rupr) iss.push(["warn", `Нет русской подсказки: ${w.word}`, w.id]); if (!w.ex) iss.push(["warn", `Нет примера: ${w.word}`, w.id]); if (!LEVELS.includes(w.level)) iss.push(["err", `Неверный уровень у ${w.word}`, w.id]); if (w.ai) iss.push(["info", `Добавлено AI, требует проверки: ${w.word}`, w.id]); });
  LEVELS.forEach(L => GRAMMAR_TOPICS[L].forEach(t => { const [n, id] = t.split("|"); const l = GRAMMAR_LESSONS[id] || CUSTOM_LESSONS[id]; if (!l) iss.push(["info", `Тема без авторского урока (используется AI-генерация): ${L} ${n}`]); else { [...(l.ex || []), ...(l.quiz || [])].forEach((x, i) => { if (x.o && (x.a < 0 || x.a >= x.o.length)) iss.push(["err", `Ошибка в упражнении ${i + 1} урока «${n}»: неверный индекс ответа`]); if (!x.o && !(Array.isArray(x.a) && x.a.length)) iss.push(["err", `Упражнение ${i + 1} урока «${n}» без ответа`]); }); } }));
  if (!Audio.hasBrowser() && !Audio.tts) iss.push(["err", "Озвучка недоступна в текущем браузере: аудиокнопки не будут работать."]);
  const per = Object.fromEntries(LEVELS.map(l => [l, VOCAB.filter(w => w.level === l).length])); const target = { A1: 600, A2: 800, B1: 1000, B2: 1200, C1: 1500, C2: 1500 }; LEVELS.forEach(l => { if (per[l] < target[l]) iss.push(["info", `Уровень ${l}: ${per[l]} из целевых ${target[l]} слов — пополните базу импортом`]); });
  return iss;
}
VIEWS.admin = v => {
  const owner = Cloud.user?.isOwner?.() ?? false; const s = S();
  let tab = "words";
  const draw = () => {
    const iss = contentIssues();
    v.innerHTML = `<h1>Админ-панель</h1><p class="sub">Управление контентом: слова, уроки, упражнения, импорт CSV/JSON и проверка полноты.</p>
    <div class="${owner ? "note" : "warn"}" style="margin-bottom:12px;font-size:14px">${owner ? "Вы владелец страницы: изменения можно опубликовать для всех учеников (общая база)." : Cloud.db ? "Изменения сохраняются в вашем профиле. Публиковать в общую базу может только владелец страницы." : "Изменения сохраняются в вашем профиле в этом браузере."}</div>
    <div class="tabs">${[["words", "Слова"], ["import", "Импорт CSV/JSON"], ["lessons", "Уроки грамматики"], ["check", `Проверка контента (${iss.filter(i => i[0] === "err").length}⛔ ${iss.filter(i => i[0] === "warn").length}⚠️)`], ["stats", "Статистика базы"]].map(([k, n]) => `<button class="tab ${tab === k ? "on" : ""}" data-t="${k}">${n}</button>`).join("")}</div><div id="ap"></div>`;
    $$("[data-t]", v).forEach(b => b.onclick = () => { tab = b.dataset.t; draw(); });
    const ap = $("#ap");
    if (tab === "words") {
      ap.innerHTML = `<div class="grid g2"><div class="card stack"><h3 id="fTitle">Добавить / изменить слово</h3><div class="grid" style="grid-template-columns:1fr 1fr;gap:8px">
      <div><label class="f">Слово *</label><input type="text" id="aW"></div><div><label class="f">Перевод *</label><input type="text" id="aR"></div>
      <div><label class="f">Уровень</label><select id="aL">${LEVELS.map(l => `<option>${l}</option>`).join("")}</select></div><div><label class="f">Часть речи</label><select id="aP">${Object.entries(POS).map(([k, n]) => `<option value="${k}">${n}</option>`).join("")}</select></div>
      <div><label class="f">IPA *</label><input type="text" id="aI" placeholder="ˈæpl"></div><div><label class="f">Русская подсказка</label><input type="text" id="aRp" placeholder="авто из IPA"></div>
      <div style="grid-column:1/-1"><label class="f">Пример (EN)</label><input type="text" id="aE"></div><div style="grid-column:1/-1"><label class="f">Перевод примера</label><input type="text" id="aEr"></div>
      <div><label class="f">Тема (ключ)</label><input type="text" id="aT" placeholder="food" list="topics"><datalist id="topics">${Object.keys(TOPIC_NAMES).map(k => `<option value="${k}">${TOPIC_NAMES[k]}</option>`).join("")}</datalist></div><div><label class="f">Формы</label><input type="text" id="aF"></div>
      <div><label class="f">Синонимы</label><input type="text" id="aS"></div><div><label class="f">Антонимы</label><input type="text" id="aA"></div>
      <div><label class="f">Сочетания</label><input type="text" id="aC"></div><div><label class="f">Типичная ошибка</label><input type="text" id="aM"></div></div>
      <div class="row"><button class="btn pri" id="aSave">Сохранить</button><button class="btn" id="aAuto">Русская подсказка из IPA</button><span class="fb-no" id="aErr"></span></div></div>
      <div class="card stack"><h3>Найти слово для редактирования</h3><input type="search" id="aQ" placeholder="Поиск…"><div id="aList"></div><h3>Добавленные вами (${s.custom.words.length})</h3><div class="muted" style="font-size:13px">${s.custom.words.slice(-15).map(w => esc(w.word)).join(", ") || "—"}</div>${owner ? `<button class="btn acc" id="aPub">☁️ Опубликовать мой контент для всех</button>` : ""}</div></div>`;
      const f = id => $("#" + id); const fill = w => { f("aW").value = w.word; f("aR").value = w.ru; f("aL").value = w.level; f("aP").value = w.pos; f("aI").value = w.ipa; f("aRp").value = w.rupr; f("aE").value = w.ex; f("aEr").value = w.exru; f("aT").value = w.topic; f("aF").value = w.forms; f("aS").value = w.syn; f("aA").value = w.ant; f("aC").value = w.col; f("aM").value = w.mis; f("fTitle").textContent = "Изменить: " + w.word; };
      f("aQ").oninput = e => { const q = e.target.value; f("aList").innerHTML = q.length < 2 ? "" : searchWords(q).slice(0, 8).map(w => `<div class="row between" style="border-bottom:1px solid var(--line);padding:4px 0"><span>${lv(w.level)} <b>${esc(w.word)}</b> — ${esc(w.ru)}</span><button class="btn sm" data-ed="${esc(w.id)}">Изменить</button></div>`).join(""); $$("[data-ed]").forEach(b => b.onclick = () => fill(VBYID[b.dataset.ed])); };
      f("aAuto").onclick = () => { f("aRp").value = ipaToRu(f("aI").value); };
      f("aSave").onclick = () => { const w = { level: f("aL").value, word: f("aW").value.trim(), pos: f("aP").value, ru: f("aR").value.trim(), ipa: f("aI").value.trim().replace(/^\/|\/$/g, ""), rupr: f("aRp").value.trim(), ex: f("aE").value.trim(), exru: f("aEr").value.trim(), topic: f("aT").value.trim() || "custom", forms: f("aF").value, syn: f("aS").value, ant: f("aA").value, col: f("aC").value, mis: f("aM").value };
        if (!w.word || !w.ru || !w.ipa) return f("aErr").textContent = "Заполните слово, перевод и IPA (IPA нужна для корректного произношения)."; if (!w.rupr) w.rupr = ipaToRu(w.ipa);
        const nw = addWord({ ...w, id: w.level + ":" + w.word.toLowerCase() }); const ci = s.custom.words.findIndex(x => x.id === nw.id); ci >= 0 ? (s.custom.words[ci] = nw) : s.custom.words.push(nw); if (!TOPIC_NAMES[w.topic]) TOPIC_NAMES[w.topic] = w.topic; Store.save(true); toast("Слово сохранено"); draw(); };
      const pb = $("#aPub"); if (pb) pb.onclick = async () => { try { await Cloud.publishShared({ words: s.custom.words, lessons: s.custom.lessons }); toast("Опубликовано для всех учеников"); } catch (e) { toast("Не удалось: " + (e.message || e)); } };
    }
    if (tab === "import") {
      ap.innerHTML = `<div class="card stack"><h3>Пакетный импорт слов</h3><p class="muted" style="font-size:14px"><b>CSV</b> (разделитель — запятая или точка с запятой, первая строка — заголовки):<br><span class="kbd">word,translation,pos,ipa,ru_pron,example,example_ru,level,topic,forms,synonyms,antonyms,collocations,mistake</span><br><b>JSON</b>: массив объектов с теми же полями.<br>Если ru_pron не указан, он будет создан автоматически из IPA. Строки без слова, перевода или IPA пропускаются.</p>
      <input type="file" id="iFile" accept=".csv,.json,.txt"><textarea id="iTxt" placeholder="…или вставьте CSV/JSON сюда"></textarea><div class="row"><button class="btn pri" id="iGo">Импортировать</button><button class="btn" id="iEx">Вставить пример</button><button class="btn" id="iDump">📋 Экспорт всей базы (JSON)</button></div><div id="iRes"></div></div>`;
      $("#iFile").onchange = e => { const fl = e.target.files[0]; if (!fl) return; const r = new FileReader(); r.onload = () => $("#iTxt").value = r.result; r.readAsText(fl); };
      $("#iEx").onclick = () => $("#iTxt").value = "word,translation,pos,ipa,ru_pron,example,example_ru,level,topic\nkettle,чайник,n,ˈketl,кэ́тл,I put the kettle on.,Я поставил чайник.,A2,house2\nthorough,тщательный,adj,ˈθʌrə,,She did a thorough job.,Она тщательно выполнила работу.,B2,abstract";
      $("#iDump").onclick = async () => { const data = JSON.stringify(VOCAB.map(w => ({ word: w.word, translation: w.ru, pos: w.pos, ipa: w.ipa, ru_pron: w.rupr, example: w.ex, example_ru: w.exru, level: w.level, topic: w.topic, forms: w.forms, synonyms: w.syn, antonyms: w.ant, collocations: w.col, mistake: w.mis }))); try { await navigator.clipboard.writeText(data); toast(`Скопировано: ${VOCAB.length} слов`); } catch { modal(`<h2>Экспорт</h2><textarea style="min-height:300px">${esc(data)}</textarea>`); } };
      $("#iGo").onclick = () => { const txt = $("#iTxt").value.trim(); let rows = []; try { if (txt.startsWith("[")) rows = JSON.parse(txt); else { const lines = txt.split(/\r?\n/).filter(Boolean); const sep = lines[0].includes(";") ? ";" : ","; const parseLine = l => { const out = []; let cur = "", q = false; for (const ch of l) { if (ch === '"') q = !q; else if (ch === sep && !q) { out.push(cur); cur = ""; } else cur += ch; } out.push(cur); return out.map(x => x.trim()); }; const hd = parseLine(lines[0]).map(h => h.toLowerCase()); rows = lines.slice(1).map(l => { const c = parseLine(l); return Object.fromEntries(hd.map((h, i) => [h, c[i] || ""])); }); } } catch (e) { $("#iRes").innerHTML = `<div class="err">Не удалось разобрать данные: ${esc(e.message)}</div>`; return; }
        let ok = 0, skip = [], upd = 0; rows.forEach((r, i) => { const w = { word: (r.word || "").trim(), ru: r.translation || r.ru || "", pos: r.pos || "n", ipa: (r.ipa || "").replace(/^\/|\/$/g, ""), rupr: r.ru_pron || r.rupr || "", ex: r.example || r.ex || "", exru: r.example_ru || r.exru || "", level: (r.level || "A1").toUpperCase(), topic: r.topic || "custom", forms: r.forms || "", syn: r.synonyms || r.syn || "", ant: r.antonyms || r.ant || "", col: r.collocations || r.col || "", mis: r.mistake || r.mis || "" }; if (!w.word || !w.ru || !w.ipa || !LEVELS.includes(w.level)) { skip.push(i + 2); return; } if (!w.rupr) w.rupr = ipaToRu(w.ipa); const id = w.level + ":" + w.word.toLowerCase(); if (VBYID[id]) upd++; else ok++; const nw = addWord({ ...w, id }); const ci = s.custom.words.findIndex(x => x.id === id); ci >= 0 ? (s.custom.words[ci] = nw) : s.custom.words.push(nw); if (!TOPIC_NAMES[w.topic]) TOPIC_NAMES[w.topic] = w.topic; });
        Store.save(true); $("#iRes").innerHTML = `<div class="note">Добавлено: <b>${ok}</b> · обновлено: <b>${upd}</b> · пропущено: <b>${skip.length}</b>${skip.length ? ` (строки ${skip.slice(0, 20).join(", ")}${skip.length > 20 ? "…" : ""}: нет слова, перевода, IPA или неверный уровень)` : ""}</div>`; };
    }
    if (tab === "lessons") {
      const opts = LEVELS.flatMap(L => GRAMMAR_TOPICS[L].map(t => [L, ...t.split("|")]));
      ap.innerHTML = `<div class="card stack"><h3>Создать или изменить урок</h3><div><label class="f">Тема</label><select id="lT">${opts.map(([L, n, id]) => `<option value="${id}">${L} · ${esc(n)}${GRAMMAR_LESSONS[id] ? " (встроенный)" : CUSTOM_LESSONS[id] || s.custom.lessons[id] ? " (ваш)" : ""}</option>`).join("")}</select></div>
      <p class="muted" style="font-size:13px">Урок — JSON со структурой: explain (HTML), formulas[], aff/neg/q [[EN,RU]], table (HTML), exceptions (HTML), mistakes[], ex[{q,o[],a,e}] (для ввода ответа: a — массив допустимых ответов), quiz[], summary. Загрузите текущий урок, отредактируйте и сохраните.</p>
      <div class="row"><button class="btn" id="lLoad">Загрузить текущий</button><button class="btn" id="lTpl">Шаблон</button></div><textarea id="lJ" style="min-height:320px;font-family:ui-monospace,monospace;font-size:13px"></textarea><div class="row"><button class="btn pri" id="lSave">Сохранить урок</button><span id="lErr" class="fb-no"></span></div>
      <h3>Добавить упражнение к уроку</h3><div class="grid" style="grid-template-columns:2fr 2fr 1fr;gap:8px"><input type="text" id="eQ" placeholder="Вопрос с ___"><input type="text" id="eO" placeholder="Варианты через | (пусто — ввод ответа)"><input type="text" id="eA" placeholder="Ответ"></div><input type="text" id="eE" placeholder="Объяснение (по-русски)"><button class="btn" id="eAdd">Добавить упражнение</button></div>`;
      const cur = () => $("#lT").value; const getL = id => s.custom.lessons[id] || CUSTOM_LESSONS[id] || GRAMMAR_LESSONS[id] || s.gen[id];
      $("#lLoad").onclick = () => { const l = getL(cur()); $("#lJ").value = l ? JSON.stringify(l, null, 2) : "Урока пока нет — нажмите «Шаблон»."; };
      $("#lTpl").onclick = () => { const m = topicMeta(cur()); $("#lJ").value = JSON.stringify({ level: m.L, title: m.title, explain: "<p>Объяснение…</p>", formulas: [""], aff: [["", ""]], neg: [["", ""]], q: [["", ""]], table: "", exceptions: "", mistakes: [""], ex: [{ q: "___", o: ["", "", ""], a: 0, e: "" }], quiz: [{ q: "", o: ["", ""], a: 0, e: "" }], summary: "" }, null, 2); };
      $("#lSave").onclick = () => { try { const l = JSON.parse($("#lJ").value); if (!l.explain || !Array.isArray(l.ex)) throw new Error("Нужны поля explain и ex[]"); s.custom.lessons[cur()] = l; CUSTOM_LESSONS[cur()] = l; Store.save(true); toast("Урок сохранён"); $("#lErr").textContent = ""; } catch (e) { $("#lErr").textContent = "Ошибка JSON: " + e.message; } };
      $("#eAdd").onclick = () => { const id = cur(); const base = JSON.parse(JSON.stringify(getL(id) || null)); if (!base) return toast("Сначала создайте урок"); const o = $("#eO").value.split("|").map(x => x.trim()).filter(Boolean); const a = $("#eA").value.trim(); const ex = o.length ? { q: $("#eQ").value, o, a: Math.max(0, o.indexOf(a)), e: $("#eE").value } : { q: $("#eQ").value, a: a.split("/").map(x => x.trim()), e: $("#eE").value }; if (!ex.q || !a) return toast("Заполните вопрос и ответ"); if (o.length && !o.includes(a)) return toast("Ответ должен совпадать с одним из вариантов"); base.ex.push(ex); s.custom.lessons[id] = base; CUSTOM_LESSONS[id] = base; Store.save(true); toast("Упражнение добавлено"); $("#lJ").value = JSON.stringify(base, null, 2); };
    }
    if (tab === "check") ap.innerHTML = `<div class="card stack"><h3>Проверка полноты контента</h3><p class="muted" style="font-size:13px">⛔ ошибки · ⚠️ предупреждения · ℹ️ информация</p>${iss.length ? iss.slice(0, 300).map(([t, m, id]) => `<div class="${t === "err" ? "err" : t === "warn" ? "warn" : "note"}" style="font-size:14px;padding:8px 12px">${t === "err" ? "⛔" : t === "warn" ? "⚠️" : "ℹ️"} ${esc(m)} ${id ? `<a href="#" data-act="word" data-id="${esc(id)}">открыть</a>` : ""}</div>`).join("") : '<div class="note">Проблем не найдено.</div>'}</div>`;
    if (tab === "stats") { const per = LEVELS.map(l => [l, VOCAB.filter(w => w.level === l).length]); ap.innerHTML = `<div class="grid g2"><div class="card"><h3>Слов по уровням</h3>${barChart(per, Math.max(...per.map(x => x[1])))}<table class="t">${per.map(([l, n]) => `<tr><td>${lv(l)}</td><td>${n} слов</td><td>${[...new Set(VOCAB.filter(w => w.level === l).map(w => w.topic))].length} тем</td></tr>`).join("")}</table></div><div class="card"><h3>Учебные материалы</h3><table class="t"><tr><td>Тем грамматики</td><td>${Object.values(GRAMMAR_TOPICS).flat().length}</td></tr><tr><td>Авторских уроков</td><td>${Object.keys(GRAMMAR_LESSONS).length + Object.keys(CUSTOM_LESSONS).length}</td></tr><tr><td>Текстов Reading</td><td>${READING.length}</td></tr><tr><td>Аудио Listening</td><td>${LISTENING.length}</td></tr><tr><td>Заданий Writing</td><td>${WRITING.length}</td></tr><tr><td>Вопросов Speaking</td><td>${SPEAKING.length}</td></tr><tr><td>Предложений Listen and Type</td><td>${DET_LISTEN.length}</td></tr><tr><td>Псевдослов (Read and Select)</td><td>${DET_PSEUDO.length}</td></tr><tr><td>Фраз и идиом</td><td>${Object.values(PHRASES).flat().length}</td></tr></table></div></div>`; }
  };
  draw();
};
